-- Новости и объявления из T19. Системные уведомления приходят по событиям.
INSERT INTO notifications (id, type, title, body, important, requires_ack, audience_kind,
                           audience_faculty_id, author_id, author_label, created_at) VALUES
('71000000-0000-4000-8000-000000000001', 'news', 'Справку с места учёбы можно скачать сразу', 'В разделе «Заявки» выберите «Справка с места учёбы» и укажите, для чего она нужна. После отправки заявки откроется карточка с готовым PDF. Там же указаны код и страница проверки справки.', false, false, 'all', NULL, '40000000-0000-4000-8000-000000000003', 'Администрация', '2026-11-12 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000002', 'news', 'Расписание до конца семестра можно перенести в календарь', 'В разделе «Расписание» нажмите «Скачать для календаря». В файле будут занятия с сегодняшнего дня до конца семестра. Импортируйте файл в свой календарь. Если занятие перенесут после скачивания, новое время будет видно в кабинете: события в календаре автоматически не обновятся.', false, false, 'all', NULL, '40000000-0000-4000-8000-000000000003', 'Администрация', '2026-11-13 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000003', 'news', 'ФМО: где искать изменения в расписании на 16–22 ноября', 'На неделе с 16 по 22 ноября проверьте метки рядом с занятиями. По ним видно, отменили ли пару, перенесли её или поменяли аудиторию. Если изменилось время занятия, откройте расписание на новую дату.', false, false, 'faculty', '10000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 'Деканат ФМО', '2026-11-16 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000004', 'news', 'МЭО: до конца ноября можно подать заявление на материальную помощь', 'Приём заявлений открыт до 30 ноября. В каталоге услуг выберите «Материальная помощь», опишите ситуацию и приложите документы, которые подтверждают основание. Если деканат попросит уточнение, оно появится в карточке заявки.', false, false, 'faculty', '10000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000002', 'Деканат МЭО', '2026-11-20 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000005', 'news', 'МЭО: как проверить баллы за работы перед зачётами', 'В разделе «Успеваемость» откройте «Текущий семестр», найдите дисциплину и разверните «Контрольные точки». Там указаны баллы за отдельные работы. Если за сданную работу балл ещё не появился, уточните у преподавателя, когда ждать результат.', false, false, 'faculty', '10000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000002', 'Деканат МЭО', '2026-11-21 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000006', 'news', 'ФМО: первый экзамен зимней сессии — 12 января', 'У группы МО-24-03 зимняя сессия начнётся с экзамена по теории международных отношений 12 января в 9:00. Перед экзаменом проверьте дату и время в дедлайнах. Аудиторию уточните в деканате.', false, false, 'faculty', '10000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 'Деканат ФМО', '2026-11-21 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000007', 'announcement', 'ФМО: проверьте время декабрьских зачётов', 'Для группы МО-24-03 зачёт по международному публичному праву указан на 18 декабря в 10:30, а по английскому языку — на 22 декабря в 12:00. Если вы из другой группы ФМО, проверьте даты в своих дедлайнах. Когда прочитаете, нажмите «Ознакомлен(а)».', true, true, 'faculty', '10000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 'Деканат ФМО', '2026-11-14 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000008', 'announcement', 'МЭО: срок сдачи курсовой для МЭО-23-02', 'Группа МЭО-23-02 сдаёт курсовую 5 декабря. Уточните у преподавателя формат работы и способ передачи файла. Если возник вопрос о сроке, напишите в деканат и укажите группу и дисциплину. Когда прочитаете, нажмите «Ознакомлен(а)».', true, true, 'faculty', '10000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000002', 'Деканат МЭО', '2026-11-14 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000009', 'announcement', 'ФМО: если нужно узнать дату пересдачи', 'Если в «Успеваемости» указан долг, уточните в деканате дату пересдачи и порядок записи. В заявке «Вопрос в деканат» выберите тему «Учебный процесс» и укажите дисциплину и семестр, за который остался долг.', false, false, 'faculty', '10000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 'Деканат ФМО', '2026-11-21 09:00:00+03:00'),
('71000000-0000-4000-8000-000000000010', 'announcement', 'МЭО: проверьте язык и период перед заказом транскрипта', 'Если выписка нужна для отбора на стажировку, сначала уточните у организаторов, за какой период они ждут оценки. В заявке можно выбрать весь период обучения или последний семестр, а также русский или английский язык.', false, false, 'faculty', '10000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000002', 'Деканат МЭО', '2026-11-21 09:00:00+03:00');
